/**
 * Backend REST & WebSocket API Client.
 * Security rule: NEVER stores AI provider API keys in localStorage/sessionStorage or calls AI providers directly.
 * Only holds the operator's RBAC session JWT in memory/sessionStorage.
 */

const TOKEN_STORAGE_KEY = 'ai_biz_sim_session_jwt';

export function getSessionToken(): string | null {
  try {
    return sessionStorage.getItem(TOKEN_STORAGE_KEY);
  } catch {
    return null;
  }
}

export function setSessionToken(token: string | null): void {
  try {
    if (token) {
      sessionStorage.setItem(TOKEN_STORAGE_KEY, token);
    } else {
      sessionStorage.removeItem(TOKEN_STORAGE_KEY);
    }
  } catch {
    // ignore storage errors in restricted environments
  }
}

export async function apiRequest<T>(
  path: string,
  options: RequestInit = {},
): Promise<T> {
  const token = getSessionToken();
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    ...(options.headers as Record<string, string> | undefined),
  };
  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
  }

  const res = await fetch(path, {
    ...options,
    headers,
  });

  if (!res.ok) {
    let errDetail = `HTTP ${res.status}`;
    try {
      const errJson = await res.json();
      errDetail = errJson.detail || errJson.error || errDetail;
    } catch {
      // ignore json parse failure
    }
    throw new Error(errDetail);
  }

  return (await res.json()) as T;
}

export function connectEventSocket(
  getLastSeq: () => number,
  onEvent: (ev: Record<string, unknown>) => void,
  onStatusChange: (connected: boolean) => void,
): () => void {
  let ws: WebSocket | null = null;
  let closedByCaller = false;
  let reconnectTimer: ReturnType<typeof setTimeout> | null = null;

  const openSocket = () => {
    if (closedByCaller) return;
    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const sinceSeq = getLastSeq();
    const url = `${protocol}//${window.location.host}/ws/events?since_seq=${sinceSeq}`;
    try {
      ws = new WebSocket(url);
      ws.onopen = () => {
        onStatusChange(true);
      };
      ws.onmessage = (msg) => {
        try {
          const parsed = JSON.parse(msg.data);
          if (parsed && parsed.event_type && parsed.event_type !== 'HEARTBEAT') {
            onEvent(parsed);
          }
        } catch {
          // ignore malformed frames
        }
      };
      ws.onclose = () => {
        onStatusChange(false);
        if (!closedByCaller) {
          reconnectTimer = setTimeout(openSocket, 2500);
        }
      };
      ws.onerror = () => {
        ws?.close();
      };
    } catch {
      onStatusChange(false);
      if (!closedByCaller) {
        reconnectTimer = setTimeout(openSocket, 3000);
      }
    }
  };

  openSocket();

  return () => {
    closedByCaller = true;
    if (reconnectTimer) clearTimeout(reconnectTimer);
    ws?.close();
  };
}
