import React, { useState } from 'react';
import {
  Activity,
  AlertTriangle,
  ArrowRight,
  Bell,
  Building2,
  CheckCircle2,
  Cpu,
  ExternalLink,
  LayoutDashboard,
  Lock,
  OctagonAlert,
  Play,
  ShieldCheck,
  UserCheck,
  Wifi,
  WifiOff,
} from 'lucide-react';
import { apiRequest } from '../api/client';
import { useSimulatorStore, type ScreenTab } from '../stores/useSimulatorStore';
import { ExecutiveTaskApprovalModal } from './ExecutiveTaskApprovalModal';

export const TopCommandBar: React.FC = () => {
  const {
    activeTab,
    setActiveTab,
    systemStatus,
    wsConnected,
    notifications,
    approvals,
    user,
    login,
    authError,
    refreshAll,
  } = useSimulatorStore();

  const [showAuthModal, setShowAuthModal] = useState(false);
  const [showExecutiveModal, setShowExecutiveModal] = useState(false);
  const [executiveModalTab, setExecutiveModalTab] = useState<'approvals' | 'notifications'>('approvals');
  const [emailInput, setEmailInput] = useState('danhnpcd@gmail.com');
  const [pwdInput, setPwdInput] = useState('Admin@123456!');

  const unreadCount = notifications.filter((n) => !n.is_read).length;
  const pendingApprovalsCount = approvals.filter((a) => a.status === 'PENDING').length;

  const scrollToApprovalHub = () => {
    setExecutiveModalTab('approvals');
    setShowExecutiveModal(true);
  };

  const triggerEmergencyStop = async () => {
    try {
      await apiRequest('/api/control/emergency-stop', { method: 'POST' });
      await refreshAll();
    } catch (err) {
      alert(err instanceof Error ? err.message : 'Không đủ quyền kích hoạt Emergency Stop');
    }
  };

  const triggerResumeSystem = async () => {
    try {
      await apiRequest('/api/control/resume', { method: 'POST' });
      await refreshAll();
    } catch (err) {
      alert(err instanceof Error ? err.message : 'Chỉ Admin mới được khôi phục sau Emergency Stop');
    }
  };

  const tabs: Array<{ id: ScreenTab; label: string; shortLabel: string; icon: React.ReactNode }> = [
    { id: 'world', label: '1. Company World 2.5D', shortLabel: '1. Thế Giới 2.5D', icon: <Building2 className="h-4 w-4" /> },
    { id: 'api-control', label: '2. API Control Room', shortLabel: '2. Nguồn API', icon: <Cpu className="h-4 w-4" /> },
    { id: 'operations', label: '3. Operations & Finance', shortLabel: '3. Vận Hành', icon: <LayoutDashboard className="h-4 w-4" /> },
  ];

  return (
    <>
      <header className="relative z-30 flex flex-col md:flex-row md:items-center justify-between gap-2.5 border-b border-slate-800 bg-slate-950/95 px-3 py-2 sm:px-4 sm:py-2.5 backdrop-blur">
        {/* Top Header Row (Brand + Badges + Mobile Quick Actions) */}
        <div className="flex items-center justify-between gap-2 w-full md:w-auto">
          <div className="flex items-center gap-2.5">
            <div className="flex h-8 w-8 sm:h-9 sm:w-9 items-center justify-center rounded-lg border border-cyan-400/40 bg-cyan-500/15 text-cyan-300 font-bold text-xs sm:text-sm">
              2.5D
            </div>
            <div>
              <div className="flex items-center gap-1.5 sm:gap-2">
                <h1 className="text-xs sm:text-sm font-bold tracking-wide text-slate-100">
                  AI PULSE ADMIN
                </h1>
                {systemStatus?.demo_mode ? (
                  <span className="rounded-full border border-amber-400/50 bg-amber-500/15 px-1.5 py-0.2 sm:px-2 sm:py-0.5 text-[9px] sm:text-[10px] font-bold uppercase text-amber-300">
                    <span className="hidden sm:inline">DEMO SANDBOX MODE</span>
                    <span className="sm:hidden">DEMO</span>
                  </span>
                ) : (
                  <span className="rounded-full border border-emerald-400/50 bg-emerald-500/15 px-1.5 py-0.2 sm:px-2 sm:py-0.5 text-[9px] sm:text-[10px] font-bold uppercase text-emerald-300">
                    <span className="hidden sm:inline">CONTROLLED PRODUCTION</span>
                    <span className="sm:hidden">PROD</span>
                  </span>
                )}
              </div>
              <p className="text-[10px] sm:text-[11px] text-slate-400">
                Policy: <strong className="text-cyan-300">{systemStatus?.routing_mode || 'FREE_FIRST'}</strong>
                <span className="hidden sm:inline"> • Quyền: <strong className="text-slate-200">{systemStatus?.automation_level || 'LEVEL_2_SANDBOX'}</strong></span>
              </p>
            </div>
          </div>

          {/* Mobile Quick Action Buttons (Visible only on < md) */}
          <div className="flex md:hidden items-center gap-1.5">
            <button
              type="button"
              onClick={() => {
                setExecutiveModalTab(pendingApprovalsCount > 0 ? 'approvals' : 'notifications');
                setShowExecutiveModal(true);
              }}
              className={`flex items-center gap-1 rounded-lg border px-2.5 py-1 text-xs font-bold transition shadow-sm ${
                pendingApprovalsCount > 0
                  ? 'border-amber-400 bg-amber-500/25 text-amber-200 animate-pulse'
                  : 'border-cyan-500/40 bg-cyan-500/10 text-cyan-300'
              }`}
            >
              <ShieldCheck className="h-3.5 w-3.5" />
              <span>{pendingApprovalsCount > 0 ? `${pendingApprovalsCount} Duyệt` : 'Duyệt'}</span>
            </button>

            <button
              type="button"
              onClick={() => {
                setExecutiveModalTab('notifications');
                setShowExecutiveModal(true);
              }}
              className="relative rounded-lg border border-slate-700 bg-slate-900 p-1.5 text-slate-200"
              title="Thông báo hệ thống"
            >
              <Bell className="h-4 w-4" />
              {unreadCount > 0 && (
                <span className="absolute -right-1 -top-1 flex h-4 min-w-[16px] items-center justify-center rounded-full bg-rose-500 px-1 text-[9px] font-bold text-white">
                  {unreadCount}
                </span>
              )}
            </button>

            {systemStatus?.emergency_stop ? (
              <button
                type="button"
                onClick={triggerResumeSystem}
                className="rounded-lg border border-emerald-400 bg-emerald-500/20 px-2 py-1 text-[11px] font-bold text-emerald-200"
                title="Khôi phục hệ thống"
              >
                <Play className="h-3.5 w-3.5" />
              </button>
            ) : (
              <button
                type="button"
                onClick={triggerEmergencyStop}
                className="rounded-lg border border-rose-500 bg-rose-600 px-2 py-1 text-[11px] font-bold text-white shadow"
                title="Dừng khẩn cấp"
              >
                <OctagonAlert className="h-3.5 w-3.5" />
              </button>
            )}
          </div>
        </div>

        {/* Main Screen Switcher (Tabs) */}
        <nav className="flex w-full md:w-auto items-center justify-between sm:justify-start gap-1 rounded-xl border border-slate-800 bg-slate-900/90 p-1">
          {tabs.map((t) => (
            <button
              key={t.id}
              type="button"
              onClick={() => setActiveTab(t.id)}
              className={`flex-1 sm:flex-initial flex items-center justify-center gap-1.5 rounded-lg px-2 sm:px-3 py-1.5 text-xs font-semibold transition ${
                activeTab === t.id
                  ? 'bg-cyan-500 text-slate-950 shadow'
                  : 'text-slate-300 hover:bg-slate-800 hover:text-white'
              }`}
            >
              {t.icon}
              <span className="hidden sm:inline">{t.label}</span>
              <span className="sm:hidden">{t.shortLabel}</span>
            </button>
          ))}
        </nav>

        {/* Desktop Controls (Hidden on mobile) */}
        <div className="hidden md:flex items-center gap-2">
          <div className="hidden xl:flex items-center gap-3 rounded-lg border border-slate-800 bg-slate-900/80 px-3 py-1.5 text-xs">
            <span className="flex items-center gap-1 text-cyan-300">
              <Activity className="h-3.5 w-3.5" />
              Agents: {systemStatus?.active_agents ?? 0}/{systemStatus?.total_agents ?? 8}
            </span>
            <span className="text-slate-600">|</span>
            <span className="text-emerald-300">Xong: {systemStatus?.completed_tasks ?? 0}</span>
            <span className="text-amber-300">Chờ: {systemStatus?.waiting_tasks ?? 0}</span>
            {wsConnected ? (
              <span className="flex items-center gap-1 text-emerald-400" title="WebSocket Live">
                <Wifi className="h-3.5 w-3.5" /> Live
              </span>
            ) : (
              <span className="flex items-center gap-1 text-amber-400" title="Sync HTTP">
                <WifiOff className="h-3.5 w-3.5" /> Sync
              </span>
            )}
          </div>

          {/* Quick Approval Alert Pill */}
          <button
            type="button"
            onClick={() => {
              setExecutiveModalTab(pendingApprovalsCount > 0 ? 'approvals' : 'notifications');
              setShowExecutiveModal(true);
            }}
            className={`flex items-center gap-1.5 rounded-lg border px-2.5 py-1.5 text-xs font-bold transition shadow-sm ${
              pendingApprovalsCount > 0
                ? 'border-amber-400/80 bg-amber-500/25 text-amber-200 animate-pulse hover:bg-amber-500/35'
                : 'border-cyan-500/40 bg-cyan-500/10 text-cyan-300 hover:bg-cyan-500/20'
            }`}
            title="Trung Tâm Phê Duyệt & Tác Vụ Cần Làm"
          >
            <ShieldCheck className="h-4 w-4 text-cyan-400" />
            <span>{pendingApprovalsCount > 0 ? `${pendingApprovalsCount} Việc Cần Duyệt` : 'Duyệt & Tác Vụ'}</span>
          </button>

          {/* Notifications Button */}
          <button
            type="button"
            onClick={() => {
              setExecutiveModalTab('notifications');
              setShowExecutiveModal(true);
            }}
            className="relative rounded-lg border border-slate-700 bg-slate-900 p-2 text-slate-200 hover:border-cyan-400 transition"
            title="Thông báo hệ thống & Duyệt việc"
          >
            <Bell className="h-4 w-4" />
            {unreadCount > 0 && (
              <span className="absolute -right-1 -top-1 flex h-4 min-w-[16px] items-center justify-center rounded-full bg-rose-500 px-1 text-[10px] font-bold text-white">
                {unreadCount}
              </span>
            )}
          </button>

          {/* RBAC Account Switcher */}
          <button
            type="button"
            onClick={() => setShowAuthModal(true)}
            className="flex items-center gap-1.5 rounded-lg border border-slate-700 bg-slate-900 px-2.5 py-1.5 text-xs text-slate-200 hover:border-cyan-400"
          >
            <UserCheck className="h-3.5 w-3.5 text-cyan-400" />
            <span>{user ? (user.email.length > 20 ? 'Admin' : user.email) : 'Đăng nhập'}</span>
          </button>

          {/* EMERGENCY STOP / RESUME */}
          {systemStatus?.emergency_stop ? (
            <button
              type="button"
              onClick={triggerResumeSystem}
              className="flex items-center gap-1.5 rounded-lg border border-emerald-400 bg-emerald-500/20 px-3 py-1.5 text-xs font-bold text-emerald-200 hover:bg-emerald-500/30"
            >
              <Play className="h-4 w-4" />
              KHÔI PHỤC HỆ THỐNG
            </button>
          ) : (
            <button
              type="button"
              onClick={triggerEmergencyStop}
              className="flex items-center gap-1.5 rounded-lg border border-rose-500 bg-rose-600 px-3 py-1.5 text-xs font-bold text-white shadow-lg shadow-rose-950/50 hover:bg-rose-500"
            >
              <OctagonAlert className="h-4 w-4" />
              EMERGENCY STOP
            </button>
          )}
        </div>
      </header>

      {/* Responsive Full-Featured Executive Approval & Task Modal */}
      <ExecutiveTaskApprovalModal
        isOpen={showExecutiveModal}
        onClose={() => setShowExecutiveModal(false)}
        initialTab={executiveModalTab}
      />

      {/* RBAC Login / Role Testing Modal */}
      {showAuthModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4">
          <div className="w-full max-w-md rounded-2xl border border-slate-700 bg-slate-900 p-5 shadow-2xl">
            <div className="flex items-center justify-between border-b border-slate-800 pb-3">
              <div className="flex items-center gap-2">
                <ShieldCheck className="h-5 w-5 text-cyan-400" />
                <h2 className="text-sm font-bold text-white">Xác thực Người Vận Hành (RBAC)</h2>
              </div>
              <button
                type="button"
                onClick={() => setShowAuthModal(false)}
                className="text-xs text-slate-400 hover:text-white"
              >
                Đóng
              </button>
            </div>

            <div className="mt-3 rounded-lg border border-amber-500/30 bg-amber-500/10 p-2.5 text-[11px] text-amber-200">
              <Lock className="mr-1 inline h-3.5 w-3.5" />
              Lưu ý bảo mật: Tài khoản đăng nhập người dùng (kể cả Google OAuth) tách biệt hoàn toàn với API Key của nhà cung cấp AI.
            </div>

            <div className="mt-3 flex gap-1.5">
              <button
                type="button"
                onClick={() => {
                  setEmailInput('admin@simulator.local');
                  setPwdInput('Admin@123456!');
                }}
                className="rounded border border-slate-700 bg-slate-800 px-2 py-1 text-[11px] text-cyan-300"
              >
                Điền nhanh Admin
              </button>
              <button
                type="button"
                onClick={() => {
                  setEmailInput('operator@simulator.local');
                  setPwdInput('Operator@123456!');
                }}
                className="rounded border border-slate-700 bg-slate-800 px-2 py-1 text-[11px] text-emerald-300"
              >
                Điền nhanh Operator
              </button>
              <button
                type="button"
                onClick={() => {
                  setEmailInput('viewer@simulator.local');
                  setPwdInput('Viewer@123456!');
                }}
                className="rounded border border-slate-700 bg-slate-800 px-2 py-1 text-[11px] text-slate-300"
              >
                Điền nhanh Viewer (Read-Only)
              </button>
            </div>

            <form
              className="mt-3 space-y-3"
              onSubmit={async (e) => {
                e.preventDefault();
                const ok = await login(emailInput, pwdInput);
                if (ok) setShowAuthModal(false);
              }}
            >
              <div>
                <label className="block text-xs text-slate-400">Email</label>
                <input
                  type="email"
                  value={emailInput}
                  onChange={(e) => setEmailInput(e.target.value)}
                  className="mt-1 w-full rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-xs text-white"
                />
              </div>
              <div>
                <label className="block text-xs text-slate-400">Mật khẩu</label>
                <input
                  type="password"
                  value={pwdInput}
                  onChange={(e) => setPwdInput(e.target.value)}
                  className="mt-1 w-full rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-xs text-white"
                />
              </div>
              {authError && <p className="text-xs text-rose-400">{authError}</p>}
              <button
                type="submit"
                className="w-full rounded-lg bg-cyan-500 py-2 text-xs font-bold text-slate-950 hover:bg-cyan-400"
              >
                Chuyển Phiên Đăng Nhập
              </button>
            </form>
          </div>
        </div>
      )}
    </>
  );
};
